CREATE TABLE t0(id INTEGER PRIMARY KEY, c0, c1 TEXT, c2 VARCHAR(10) CHECK(c2 IS NULL OR length(c2) < 40), c3 VARCHAR(10));
INSERT INTO t0(c0, c1, c2, c3) VALUES(NULL, -4, x'aacecf32', -840);
INSERT INTO t0(c0, c1, c2, c3) VALUES(74, -18, NULL, 5);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3) VALUES(832, -12.3, 1, NULL);
INSERT INTO t0(c0, c1, c2, c3) VALUES(-8, 'tau', -2, NULL);
INSERT INTO t0(c0, c1, c2, c3) VALUES(x'c7d85390', -656, -810, NULL);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 TEXT, c1 INTEGER NOT NULL DEFAULT 0, c2 ANY COLLATE NOCASE, ref INTEGER REFERENCES t0(id)) STRICT;
INSERT OR IGNORE INTO t1(c0, c1, c2, ref) VALUES('pi', -211, 'it''s', 3);
INSERT INTO t1(c0, c1, c2, ref) VALUES('x_y', 486, '0x1F', 5);
INSERT OR IGNORE INTO t1(c0, c1, c2, ref) VALUES('it''s', NULL, 'chi', 8);
INSERT INTO t1(c0, c1, c2, ref) VALUES('eta', 347, 0, NULL);
INSERT INTO t1(c0, c1, c2, ref) VALUES('MU', -143, 2, NULL);
INSERT INTO t1(c0, c1, c2, ref) VALUES('nu', NULL, NULL, 5);
INSERT OR IGNORE INTO t1(c0, c1, c2, ref) VALUES('chi', -333, x'8b8b', 4);
INSERT INTO t1(c0, c1, c2, ref) VALUES('MU', 437, NULL, 1);
SELECT length('eta'), upper('eta'), lower('eta'), substr('eta', 2, 4), instr('eta', 'iota'), replace('eta', 'e', ''), trim('eta'), ltrim('eta', 'ab'), hex('eta'), quote('eta'), unicode('eta'), 'eta' LIKE 'A%', 'eta' GLOB 'a*', char(89, 405), 'eta' || 'iota', 'eta' < 'iota', 'eta' = 'iota' COLLATE NOCASE;
SELECT length('upsilon'), upper('upsilon'), lower('upsilon'), substr('upsilon', -2, 0), instr('upsilon', 'chi'), replace('upsilon', '', ''), trim('upsilon'), ltrim('upsilon', 'ab'), hex('upsilon'), quote('upsilon'), unicode('upsilon'), 'upsilon' LIKE '%a_', 'upsilon' GLOB '?', char(86, 299), 'upsilon' || 'chi', 'upsilon' < 'chi', 'upsilon' = 'chi' COLLATE NOCASE;
SELECT length('señor'), upper('señor'), lower('señor'), substr('señor', -2, 5), instr('señor', 'theta'), replace('señor', '', '_'), trim('señor'), ltrim('señor', 'ab'), hex('señor'), quote('señor'), unicode('señor'), 'señor' LIKE '%é%', 'señor' GLOB '?', char(74, 974), 'señor' || 'theta', 'señor' < 'theta', 'señor' = 'theta' COLLATE NOCASE;
SELECT length('café'), upper('café'), lower('café'), substr('café', -1, 3), instr('café', 'phi'), replace('café', 'é', 'XY'), trim('café'), ltrim('café', 'ab'), hex('café'), quote('café'), unicode('café'), 'café' LIKE '%', 'café' GLOB '?', char(66, 397), 'café' || 'phi', 'café' < 'phi', 'café' = 'phi' COLLATE NOCASE;
SELECT length('42'), upper('42'), lower('42'), substr('42', 1, 0), instr('42', 'psi'), replace('42', '', '_'), trim('42'), ltrim('42', 'ab'), hex('42'), quote('42'), unicode('42'), '42' LIKE 'A%', '42' GLOB '*', char(77, 647), '42' || 'psi', '42' < 'psi', '42' = 'psi' COLLATE NOCASE;
SELECT length('xi'), upper('xi'), lower('xi'), substr('xi', 2, 0), instr('xi', 'gamma'), replace('xi', 'é', 'XY'), trim('xi'), ltrim('xi', 'ab'), hex('xi'), quote('xi'), unicode('xi'), 'xi' LIKE '_', 'xi' GLOB '*', char(83, 847), 'xi' || 'gamma', 'xi' < 'gamma', 'xi' = 'gamma' COLLATE NOCASE;
SELECT a.id, b.id, a.c0, b.ref FROM t0 a JOIN t1 b ON b.ref = a.id ORDER BY 1, 2 LIMIT 50;
SELECT count(*) FROM t0 a JOIN t0 b USING(id) WHERE a.NOT iif(c3, id, NULL);
SELECT id, (SELECT count(*) FROM t1 WHERE t1.id <= t0.id) FROM t0 ORDER BY c2, id;
SELECT id FROM t0 WHERE id IN (SELECT id FROM t1) ORDER BY id;
SELECT id FROM t0 x WHERE NOT EXISTS (SELECT 1 FROM t1 y WHERE y.id = x.id + 0) ORDER BY id;
SELECT c3 FROM t0 UNION SELECT c2 FROM t1 ORDER BY 1 LIMIT 21 OFFSET 1;
UPDATE t0 SET c0 = typeof(coalesce(c0, 1e-7)) WHERE iif(id, 'rho', 'chi');
DELETE FROM t0 WHERE id % 2 = 1;
INSERT INTO t0(id, c0) VALUES(2, 1e-7) ON CONFLICT(id) DO UPDATE SET c0 = excluded.c0 || '!';
REPLACE INTO t0(id, c0) VALUES(6, x'cb81');
INSERT INTO t0(c0) VALUES('delta') RETURNING id, c0;
SELECT * FROM t0 ORDER BY id DESC, c0, c1, c2, c3;
